1	use std::collections::VecDeque;
2	
3	use cor24_emulator::{Assembler, EmulatorCore, StopReason};
4	use gloo::timers::callback::Timeout;
5	use web_sys::{HtmlInputElement, HtmlTextAreaElement, KeyboardEvent};
6	use yew::prelude::*;
7	
8	use crate::config::{PreludeTier, StackSize};
9	use crate::demos::DEMOS;
10	
11	/// Batch size per animation frame tick
12	const BATCH_SIZE: u64 = 50_000;
13	
14	#[derive(Clone, Copy, PartialEq, Eq)]
15	pub enum ViewMode {
16	    Cli,
17	    Split,
18	}
19	
20	pub enum Msg {
21	    Init,
22	    Tick,
23	    InputChanged(String),
24	    Eval,
25	    SetPrelude(PreludeTier),
26	    SetStack(StackSize),
27	    Reset,
28	    LoadDemo(usize),
29	    ToggleView,
30	    ToggleSwitch,
31	    ClearAll,
32	    PauseResume,
33	    ToggleTrace,
34	    /// Keydown in CLI input (Enter to eval)
35	    CliKeyDown(KeyboardEvent),
36	    /// Keydown in Split textarea (Shift-Enter to eval)
37	    SplitKeyDown(KeyboardEvent),
38	}
39	
40	pub struct Repl {
41	    emulator: EmulatorCore,
42	    /// Raw UART TX output from emulator (used by Split view)
43	    output: String,
44	    /// Interleaved transcript: UART output + echoed user input (used by CLI view)
45	    transcript: String,
46	    /// How many bytes of UART output we've already copied to transcript
47	    uart_seen: usize,
48	    input: String,
49	    status: String,
50	    running: bool,
51	    loaded: bool,
52	    waiting_for_input: bool,
53	    uart_tx_queue: VecDeque<u8>,
54	    prelude: PreludeTier,
55	    stack_size: StackSize,
56	    led_lit: bool, // true when D2 is visually lit (hardware is active-low)
57	    switch_pressed: bool,
58	    /// Ticks to wait after feeding input before checking for prompt idle.
59	    /// Prevents false "at prompt" detection when a just-fed expression
60	    /// is still being evaluated (e.g. a spin loop producing no output).
61	    feed_cooldown: u32,
62	    view_mode: ViewMode,
63	    selected_demo: Option<usize>,
64	    /// Symbol addresses from assembly labels
65	    addr_heap_next: Option<u32>,
66	    addr_sym_count: Option<u32>,
67	    addr_str_pool_next: Option<u32>,
68	    /// Live memory readings
69	    heap_used: u32,
70	    sym_used: u32,
71	    str_pool_used: u32,
72	    stack_depth: u32,
73	    /// Exponentially weighted CPU load (0.0 = idle, 1.0 = pegged)
74	    cpu_load: f64,
75	    /// Whether the instruction trace panel is visible
76	    show_trace: bool,
77	    /// Formatted trace text (last N instructions)
78	    trace_text: String,
79	    input_ref: NodeRef,
80	    cli_input_ref: NodeRef,
81	}
82	
83	const HEAP_SIZE: u32 = 32768;
84	const MAX_SYMBOLS: u32 = 512;
85	const STR_POOL_SIZE: u32 = 8192;
86	
87	impl Repl {
88	    fn load_binary(&mut self) {
89	        let asm_source = self.prelude.assembly();
90	        let mut asm = Assembler::new();
91	        let result = asm.assemble(asm_source);
92	
93	        if !result.errors.is_empty() {
94	            self.status = format!("Assembly failed: {}", result.errors[0]);
95	            self.loaded = false;
96	            return;
97	        }
98	
99	        self.emulator.hard_reset();
100	        self.emulator.set_uart_tx_busy_cycles(0); // instant TX in browser
101	        for (addr, &byte) in result.bytes.iter().enumerate() {
102	            self.emulator.write_byte(addr as u32, byte);
103	        }
104	        self.emulator.set_pc(0);
105	        self.emulator.set_reg(4, self.stack_size.initial_sp());
106	
107	        // Load pre-compiled heap snapshot if available (10x faster startup)
108	        if let Some(snap) = self.prelude.snapshot() {
109	            for (i, &byte) in snap.iter().enumerate() {
110	                self.emulator.write_byte(0x080000 + i as u32, byte);
111	            }
112	        }
113	
114	        // Capture memory pool addresses from symbol table
115	        self.addr_heap_next = result.labels.get("_heap_next").copied();
116	        self.addr_sym_count = result.labels.get("_sym_count").copied();
117	        self.addr_str_pool_next = result.labels.get("_str_pool_next").copied();
118	
119	        self.output.clear();
120	        self.transcript.clear();
121	        self.uart_seen = 0;
122	        self.uart_tx_queue.clear();
123	        self.loaded = true;
124	        self.waiting_for_input = false;
125	        self.led_lit = false;
126	        self.switch_pressed = false;
127	        self.feed_cooldown = 0;
128	        self.heap_used = 0;
129	        self.sym_used = 0;
130	        self.str_pool_used = 0;
131	        self.stack_depth = 0;
132	        self.cpu_load = 0.0;
133	        self.status = format!(
134	            "Loaded {} bytes ({}, {} stack).",
135	            result.bytes.len(),
136	            self.prelude.label(),
137	            self.stack_size.label(),
138	        );
139	
140	        self.emulator.resume();
141	        self.running = true;
142	    }
143	
144	    fn view_gauge(&self, label: &str, used: u32, total: u32) -> Html {
145	        let pct = if total > 0 {
146	            (used as f64 / total as f64 * 100.0).min(100.0)
147	        } else {
148	            0.0
149	        };
150	        let color_class = if pct < 60.0 {
151	            "gauge-green"
152	        } else if pct < 85.0 {
153	            "gauge-yellow"
154	        } else {
155	            "gauge-red"
156	        };
157	        html! {
158	            <div class="gauge-row">
159	                <span class="gauge-label">{ label }</span>
160	                <div class="gauge-track">
161	                    <div class={classes!("gauge-fill", color_class)}
162	                         style={format!("width:{}%", pct)} />
163	                </div>
164	                <span class="gauge-text">{ format!("{}/{}", used, total) }</span>
165	            </div>
166	        }
167	    }
168	
169	    fn view_cpu_gauge(&self) -> Html {
170	        let pct = (self.cpu_load * 100.0).min(100.0);
171	        let color_class = if pct < 20.0 {
172	            "gauge-green"
173	        } else if pct < 60.0 {
174	            "gauge-yellow"
175	        } else {
176	            "gauge-red"
177	        };
178	        let label = if pct < 1.0 {
179	            "idle"
180	        } else if pct > 90.0 {
181	            "pegged"
182	        } else {
183	            "running"
184	        };
185	        html! {
186	            <div class="gauge-row">
187	                <span class="gauge-label">{ "CPU" }</span>
188	                <div class="gauge-track">
189	                    <div class={classes!("gauge-fill", color_class)}
190	                         style={format!("width:{}%", pct)} />
191	                </div>
192	                <span class="gauge-text">{ label }</span>
193	            </div>
194	        }
195	    }
196	
197	    fn send_input(&mut self) {
198	        for line in self.input.lines() {
199	            let trimmed = line.trim();
200	            if trimmed.is_empty() || trimmed.starts_with(';') {
201	                continue;
202	            }
203	            for byte in line.bytes() {
204	                self.uart_tx_queue.push_back(byte);
205	            }
206	            self.uart_tx_queue.push_back(b'\n');
207	        }
208	    }
209	}
210	
211	impl Component for Repl {
212	    type Message = Msg;
213	    type Properties = ();
214	
215	    fn create(ctx: &Context<Self>) -> Self {
216	        ctx.link().send_message(Msg::Init);
217	
218	        Self {
219	            emulator: {
220	                let mut emu = EmulatorCore::new();
221	                emu.set_uart_tx_busy_cycles(0); // instant TX in browser
222	                emu
223	            },
224	            output: String::new(),
225	            transcript: String::new(),
226	            uart_seen: 0,
227	            input: String::from("(+ 1 2)"),
228	            status: "Assembling interpreter...".into(),
229	            running: false,
230	            loaded: false,
231	            waiting_for_input: false,
232	            uart_tx_queue: VecDeque::new(),
233	            prelude: PreludeTier::Standard,
234	            stack_size: StackSize::ThreeKb,
235	            led_lit: false,
236	            switch_pressed: false,
237	            feed_cooldown: 0,
238	            view_mode: ViewMode::Cli,
239	            selected_demo: None,
240	            addr_heap_next: None,
241	            addr_sym_count: None,
242	            addr_str_pool_next: None,
243	            heap_used: 0,
244	            sym_used: 0,
245	            str_pool_used: 0,
246	            stack_depth: 0,
247	            cpu_load: 0.0,
248	            show_trace: false,
249	            trace_text: String::new(),
250	            input_ref: NodeRef::default(),
251	            cli_input_ref: NodeRef::default(),
252	        }
253	    }
254	
255	    fn update(&mut self, ctx: &Context<Self>, msg: Self::Message) -> bool {
256	        match msg {
257	            Msg::Init => {
258	                self.load_binary();
259	                if self.loaded {
260	                    ctx.link().send_message(Msg::Tick);
261	                }
262	                true
263	            }
264	
265	            Msg::Tick => {
266	                if !self.running {
267	                    return false;
268	                }
269	
270	                // Feed queued bytes: poll-before-feed (match cor24-run).
271	                // Budget limits total instructions to avoid blocking the
272	                // browser when the interpreter is busy evaluating.
273	                let mut feed_budget: u32 = 10_000;
274	                while !self.uart_tx_queue.is_empty() && feed_budget > 0 {
275	                    let status = self.emulator.read_byte(0xFF0101);
276	                    if status & 0x01 != 0 {
277	                        // CPU hasn't consumed previous byte — run a bit more
278	                        self.emulator.run_batch(50);
279	                        feed_budget = feed_budget.saturating_sub(50);
280	                        continue;
281	                    }
282	                    let byte = self.uart_tx_queue.pop_front().unwrap();
283	                    self.emulator.send_uart_byte(byte);
284	                    self.emulator.run_batch(50);
285	                    feed_budget = feed_budget.saturating_sub(50);
286	                    if byte == b'\n' {
287	                        // After feeding a line, give the evaluator time
288	                        // to consume and act on it before checking for
289	                        // prompt idle (~10 ticks × 25ms = 250ms).
290	                        self.feed_cooldown = 10;
291	                        break;
292	                    }
293	                }
294	
295	                let result = self.emulator.run_batch(BATCH_SIZE);
296	
297	                // EWMA of CPU utilization: how much of the batch budget was used
298	                let utilization = result.instructions_run as f64 / BATCH_SIZE as f64;
299	                const ALPHA: f64 = 0.15; // smoothing factor
300	                self.cpu_load = self.cpu_load * (1.0 - ALPHA) + utilization * ALPHA;
301	
302	                if result.led_changed {
303	                    // LED D2 is active-low: register 0 = lit, 1 = dark
304	                    self.led_lit = self.emulator.is_led_on();
305	                }
306	
307	                // Sample memory usage from runtime globals
308	                if let Some(addr) = self.addr_heap_next {
309	                    self.heap_used = self.emulator.read_word(addr);
310	                }
311	                if let Some(addr) = self.addr_sym_count {
312	                    self.sym_used = self.emulator.read_word(addr);
313	                }
314	                if let Some(addr) = self.addr_str_pool_next {
315	                    self.str_pool_used = self.emulator.read_word(addr);
316	                }
317	                let sp = self.emulator.get_reg(4);
318	                self.stack_depth = self.stack_size.initial_sp().saturating_sub(sp);
319	
320	                let uart = self.emulator.get_uart_output();
321	                // Append new UART bytes to transcript (CLI view)
322	                if uart.len() > self.uart_seen {
323	                    self.transcript.push_str(&uart[self.uart_seen..]);
324	                    self.uart_seen = uart.len();
325	                }
326	                // Update raw output (Split view)
327	                let uart_owned = uart.to_string();
328	                if uart_owned != self.output {
329	                    self.output = uart_owned;
330	                }
331	
332	                // Capture instruction trace when panel is visible
333	                if self.show_trace {
334	                    self.trace_text = self.emulator.trace().format_last(20);
335	                }
336	
337	                match result.reason {
338	                    StopReason::CycleLimit => {
339	                        // Idle at the prompt only when ALL of:
340	                        //  1. No input remains to feed
341	                        //  2. Feed cooldown has expired (not mid-eval of
342	                        //     a just-fed expression — a spin loop like
343	                        //     delay or poll produces no UART output, so
344	                        //     the "> " suffix alone is ambiguous)
345	                        //  3. UART output ends with the REPL prompt
346	                        if self.feed_cooldown > 0 {
347	                            self.feed_cooldown -= 1;
348	                        }
349	                        let at_prompt = self.feed_cooldown == 0
350	                            && self.uart_tx_queue.is_empty()
351	                            && self.output.ends_with("> ");
352	
353	                        if at_prompt {
354	                            self.running = false;
355	                            self.waiting_for_input = true;
356	                            self.cpu_load = 0.0;
357	                            self.status = "Ready.".into();
358	                        } else {
359	                            let link = ctx.link().clone();
360	                            Timeout::new(25, move || link.send_message(Msg::Tick)).forget();
361	                        }
362	                    }
363	                    StopReason::Halted => {
364	                        self.running = false;
365	                        self.waiting_for_input = false;
366	                        self.cpu_load = 0.0;
367	                        self.status = "Program finished.".into();
368	                    }
369	                    StopReason::InvalidInstruction(byte) => {
370	                        self.running = false;
371	                        self.status = format!(
372	                            "Invalid instruction 0x{:02X} at PC=0x{:06X}",
373	                            byte,
374	                            self.emulator.pc()
375	                        );
376	                    }
377	                    StopReason::Breakpoint(addr) => {
378	                        self.running = false;
379	                        self.status = format!("Breakpoint at 0x{:06X}", addr);
380	                    }
381	                    StopReason::Paused => {
382	                        self.running = false;
383	                        self.status = "Paused.".into();
384	                    }
385	                }
386	                true
387	            }
388	
389	            Msg::InputChanged(value) => {
390	                self.input = value;
391	                false
392	            }
393	
394	            Msg::Eval => {
395	                if !self.loaded {
396	                    return true;
397	                }
398	                // Echo input to transcript (CLI view shows interleaved I/O)
399	                for line in self.input.lines() {
400	                    if !line.trim().is_empty() {
401	                        self.transcript.push_str(line);
402	                        self.transcript.push('\n');
403	                    }
404	                }
405	                self.send_input();
406	                self.status = "Evaluating...".into();
407	                self.waiting_for_input = false;
408	                if !self.running {
409	                    self.emulator.resume();
410	                    self.running = true;
411	                    ctx.link().send_message(Msg::Tick);
412	                }
413	                // In CLI mode, clear the input after sending
414	                if self.view_mode == ViewMode::Cli {
415	                    self.input.clear();
416	                }
417	                true
418	            }
419	
420	            Msg::CliKeyDown(e) => {
421	                if e.key() == "Enter" && !e.shift_key() {
422	                    e.prevent_default();
423	                    ctx.link().send_message(Msg::Eval);
424	                }
425	                false
426	            }
427	
428	            Msg::SplitKeyDown(e) => {
429	                if e.key() == "Enter" && e.shift_key() {
430	                    e.prevent_default();
431	                    ctx.link().send_message(Msg::Eval);
432	                }
433	                false
434	            }
435	
436	            Msg::SetPrelude(tier) => {
437	                if tier != self.prelude {
438	                    self.prelude = tier;
439	                    self.running = false;
440	                    self.load_binary();
441	                    if self.loaded {
442	                        ctx.link().send_message(Msg::Tick);
443	                    }
444	                }
445	                true
446	            }
447	
448	            Msg::SetStack(size) => {
449	                if size != self.stack_size {
450	                    self.stack_size = size;
451	                    self.running = false;
452	                    self.load_binary();
453	                    if self.loaded {
454	                        ctx.link().send_message(Msg::Tick);
455	                    }
456	                }
457	                true
458	            }
459	
460	            Msg::Reset => {
461	                self.running = false;
462	                self.load_binary();
463	                if self.loaded {
464	                    ctx.link().send_message(Msg::Tick);
465	                }
466	                true
467	            }
468	
469	            Msg::LoadDemo(index) => {
470	                if let Some(demo) = DEMOS.get(index) {
471	                    self.selected_demo = Some(index);
472	                    self.input = demo.source.trim().to_string();
473	                    self.prelude = demo.prelude;
474	                    self.stack_size = demo.stack;
475	                    // Always reset emulator for a clean demo run
476	                    self.running = false;
477	                    self.load_binary();
478	                    if self.loaded {
479	                        ctx.link().send_message(Msg::Tick);
480	                    }
481	                    // Switch to Split view for demos (multi-line code)
482	                    self.view_mode = ViewMode::Split;
483	                }
484	                true
485	            }
486	
487	            Msg::ToggleView => {
488	                self.view_mode = match self.view_mode {
489	                    ViewMode::Cli => ViewMode::Split,
490	                    ViewMode::Split => ViewMode::Cli,
491	                };
492	                true
493	            }
494	
495	            Msg::ToggleSwitch => {
496	                self.switch_pressed = !self.switch_pressed;
497	                self.emulator.set_button_pressed(self.switch_pressed);
498	                true
499	            }
500	
501	            Msg::ClearAll => {
502	                self.emulator.clear_uart_output();
503	                self.output.clear();
504	                self.transcript.clear();
505	                self.uart_seen = 0;
506	                self.input.clear();
507	                self.selected_demo = None;
508	                true
509	            }
510	
511	            Msg::ToggleTrace => {
512	                self.show_trace = !self.show_trace;
513	                if self.show_trace {
514	                    self.trace_text = self.emulator.trace().format_last(20);
515	                }
516	                true
517	            }
518	
