use web_sys::{HtmlSelectElement, HtmlTextAreaElement, KeyboardEvent};
use yew::prelude::*;

pub mod demos;
pub mod runner;

use demos::DEMOS;

const DEFAULT_DEMO: &str = "hello";
const MAX_INSTRS: u64 = 200_000_000;

fn default_demo_index() -> usize {
    DEMOS
        .iter()
        .position(|d| d.name == DEFAULT_DEMO)
        .unwrap_or(0)
}

pub enum Msg {
    SelectDemo(usize),
    SourceChanged(String),
    DataChanged(String),
    Run,
    SourceKeyDown(KeyboardEvent),
}

pub struct App {
    selected: usize,
    source: String,
    data: String,
    output: String,
    status: String,
    error: bool,
}

impl Component for App {
    type Message = Msg;
    type Properties = ();

    fn create(_ctx: &Context<Self>) -> Self {
        let idx = default_demo_index();
        let demo = &DEMOS[idx];
        Self {
            selected: idx,
            source: demo.source.to_string(),
            data: demo.data.unwrap_or("").to_string(),
            output: String::new(),
            status: "idle".into(),
            error: false,
        }
    }

    fn update(&mut self, _ctx: &Context<Self>, msg: Self::Message) -> bool {
        match msg {
            Msg::SelectDemo(i) => {
                if let Some(demo) = DEMOS.get(i) {
                    self.selected = i;
                    self.source = demo.source.to_string();
                    self.data = demo.data.unwrap_or("").to_string();
                    self.output.clear();
                    self.status = "idle".into();
                    self.error = false;
                }
                true
            }
            Msg::SourceChanged(v) => {
                self.source = v;
                false
            }
            Msg::DataChanged(v) => {
                self.data = v;
                false
            }
            Msg::Run => {
                self.status = "running…".into();
                self.error = false;
                let start = web_sys::window()
                    .and_then(|w| w.performance())
                    .map(|p| p.now())
                    .unwrap_or(0.0);
                match runner::run_snobol4(&self.source, &self.data, MAX_INSTRS) {
                    Ok(result) => {
                        let elapsed = web_sys::window()
                            .and_then(|w| w.performance())
                            .map(|p| p.now() - start)
                            .unwrap_or(0.0);
                        self.output = result.output;
                        self.status = format!(
                            "{} ({} instrs, {:.0} ms)",
                            if result.halted { "done" } else { result.stop_reason.as_str() },
                            result.instructions,
